function exportGLB(m){let chunks=[],views=[],acc=[],primitives=[],materials=[],off=0;function add(a,target,type,component,components){let b=new Uint8Array(a.buffer,a.byteOffset,a.byteLength),n=(b.length+3)&~3,padded=new Uint8Array(n);padded.set(b);chunks.push(padded);let v=views.length;views.push({buffer:0,byteOffset:off,byteLength:b.length,target});off+=n;let o={bufferView:v,componentType:component,count:a.length/components,type};if(target===34962&&type==='VEC3'){o.min=[Infinity,Infinity,Infinity];o.max=[-Infinity,-Infinity,-Infinity];for(let j=0;j<a.length;j++){let k=j%3;o.min[k]=Math.min(o.min[k],a[j]);o.max[k]=Math.max(o.max[k],a[j])}}acc.push(o);return acc.length-1}for(let p of m.parts){let pos=m.units==='mm'?Float32Array.from(p.pos,x=>x/1000):p.pos;let a=add(pos,34962,'VEC3',5126,3),b=add(p.norm,34962,'VEC3',5126,3),c=add(p.idx,34963,'SCALAR',5125,1);materials.push({pbrMetallicRoughness:{baseColorFactor:[...p.color,1],metallicFactor:.65,roughnessFactor:.35}});primitives.push({attributes:{POSITION:a,NORMAL:b},indices:c,material:materials.length-1})}let g={asset:{version:'2.0',generator:'Caratzon local relief'},scene:0,scenes:[{nodes:[0]}],nodes:[{mesh:0}],meshes:[{primitives}],materials,buffers:[{byteLength:off}],bufferViews:views,accessors:acc};let json=new TextEncoder().encode(JSON.stringify(g)),jlen=(json.length+3)&~3,out=new ArrayBuffer(28+jlen+off),d=new DataView(out),u=new Uint8Array(out);d.setUint32(0,0x46546c67,true);d.setUint32(4,2,true);d.setUint32(8,out.byteLength,true);d.setUint32(12,jlen,true);d.setUint32(16,0x4e4f534a,true);u.fill(32,20,20+jlen);u.set(json,20);d.setUint32(20+jlen,off,true);d.setUint32(24+jlen,0x004e4942,true);let i=28+jlen;for(let b of chunks){u.set(b,i);i+=b.length}return out}
function exportSTL(m){let count=m.parts.reduce((s,p)=>s+p.idx.length/3,0),out=new ArrayBuffer(84+50*count),d=new DataView(out);new Uint8Array(out).set(new TextEncoder().encode('Caratzon concept mesh; coordinates in mm'));d.setUint32(80,count,true);let o=84,scale=m.units==='mm'?1:1000;for(let p of m.parts)for(let i=0;i<p.idx.length;i+=3){let a=p.idx[i]*3,b=p.idx[i+1]*3,c=p.idx[i+2]*3,u=[0,1,2].map(k=>p.pos[b+k]-p.pos[a+k]),v=[0,1,2].map(k=>p.pos[c+k]-p.pos[a+k]),n=[u[1]*v[2]-u[2]*v[1],u[2]*v[0]-u[0]*v[2],u[0]*v[1]-u[1]*v[0]],l=Math.hypot(...n)||1;for(let x of n){d.setFloat32(o,x/l,true);o+=4}for(let j of [a,b,c])for(let k=0;k<3;k++){d.setFloat32(o,p.pos[j+k]*scale,true);o+=4}d.setUint16(o,0,true);o+=2}return out}
