function drawSoft(a,z,tech){let ctx=soft,w=C.width,h=C.height,scale=Math.min(w,h)*.775*z/mesh.span;ctx.fillStyle=tech?'#fff':'#141619';ctx.fillRect(0,0,w,h);const dot=(x,y,z,v)=>x*v[0]+y*v[1]+z*v[2];let tris=[],palette={gold:[.83,.63,.28],silver:[.72,.76,.8],gray:[.64,.65,.67]};for(let p of mesh.parts){let n=p.pos.length/3,proj=new Float32Array(n*3);for(let i=0;i<n;i++){let j=i*3,x=p.pos[j]-mesh.center[0],y=p.pos[j+1]-mesh.center[1],z=p.pos[j+2]-mesh.center[2];proj[j]=w/2+dot(x,y,z,a.right)*scale;proj[j+1]=h/2-dot(x,y,z,a.up)*scale;proj[j+2]=dot(x,y,z,a.forward)}let color=tech?[.55,.57,.60]:palette[$('mat').value]||p.color;for(let i=0;i<p.idx.length;i+=3){let j=p.idx[i]*3,k=p.idx[i+1]*3,l=p.idx[i+2]*3;let ax=proj[k]-proj[j],ay=proj[k+1]-proj[j+1],bx=proj[l]-proj[j],by=proj[l+1]-proj[j+1];if(ax*by-ay*bx>=0)continue;let nx=p.norm[j]+p.norm[k]+p.norm[l],ny=p.norm[j+1]+p.norm[k+1]+p.norm[l+1],nz=p.norm[j+2]+p.norm[k+2]+p.norm[l+2],len=Math.hypot(nx,ny,nz)||1;let light=Math.max(0,(-.35*dot(nx,ny,nz,a.right)+.55*dot(nx,ny,nz,a.up)+.76*dot(nx,ny,nz,a.forward))/len);let shade=.42+.7*light;let rgb=color.map(c=>Math.round(Math.min(1,c*shade)*255));tris.push([ (proj[j+2]+proj[k+2]+proj[l+2])/3,proj[j],proj[j+1],proj[k],proj[k+1],proj[l],proj[l+1],`rgb(${rgb.join(',')})`])}}tris.sort((a,b)=>a[0]-b[0]);for(let t of tris){ctx.fillStyle=t[7];ctx.strokeStyle=t[7];ctx.lineWidth=.6;ctx.beginPath();ctx.moveTo(t[1],t[2]);ctx.lineTo(t[3],t[4]);ctx.lineTo(t[5],t[6]);ctx.closePath();ctx.fill();ctx.stroke()}}

