function depth448(m){const lo=[Infinity,Infinity,Infinity],hi=[-Infinity,-Infinity,-Infinity];for(const p of m.parts)for(let i=0;i<p.pos.length;i++){const k=i%3;lo[k]=Math.min(lo[k],p.pos[i]);hi[k]=Math.max(hi[k],p.pos[i]);}const spans=hi.map((v,i)=>v-lo[i]);if(!spans.every(Number.isFinite)||spans[1]<=0)return null;const bands=Array.from({length:5},()=>[Infinity,-Infinity]);for(const p of m.parts)for(let i=0;i<p.pos.length;i+=3){const j=Math.min(4,Math.max(0,Math.floor(5*(p.pos[i+1]-lo[1])/spans[1])));bands[j][0]=Math.min(bands[j][0],p.pos[i+2]);bands[j][1]=Math.max(bands[j][1],p.pos[i+2]);}return {spans,bands:bands.map(([a,b])=>Number.isFinite(b-a)?(b-a)/spans[1]:null)};}
function updateDepth448(){const el=$('depth448');if(!el)return;el.hidden=!productionSelected();$('side448').hidden=el.hidden;if(el.hidden)return;const p=purposeState;const a=p.display.depth448||(p.display.depth448=depth448(p.display.m));const b=p.draft&&(p.draft.depth448||(p.draft.depth448=depth448(p.draft.raw)));const fmt=x=>x==null?'—':(100*x).toFixed(1)+'%';let t=T(['深度检查（假定 Y 为高度、Z 为前后；非壁厚）','Depth check (Y up, Z depth; not wall thickness)','Глубина (Y вверх, Z глубина; не толщина стенки)']);if(a&&b){t+='\n'+T(['原模型 → 无石草稿：前后深度 / 高度','Original → draft: depth / height','Исходная → черновик: глубина / высота'])+' '+fmt(a.spans[2]/a.spans[1])+' → '+fmt(b.spans[2]/b.spans[1]);for(let i=4;i>=0;i--)t+='\n'+(5-i)+' / 5: '+fmt(a.bands[i])+' → '+fmt(b.bands[i]);if(a.bands.some((v,i)=>v!=null&&v>0.025&&b.bands[i]!=null&&b.bands[i]<v*.65))t+='\n'+T(['警告：部分高度区间深度明显下降。请查看侧面；去石及模型朝向亦会影响比较。','Warning: depth decreased in some height bands. Inspect side; stone removal and orientation affect comparison.','Внимание: глубина уменьшилась; проверьте боковой вид и ориентацию.']);}else t+='\n'+T(['等待无石草稿以比较深度。','Awaiting stone-free draft for comparison.','Ожидание черновика.']);el.textContent=t;}
function purposeDownloadAllowed(){return !!mesh;}
function productionSelected(){return !!purposeState.display&&$('modelPurpose').value==='production';}
function productionDraftVisible(){const d=purposeState.draft;return !!d&&(mesh===d.raw||mesh===d.scaled);}
function sizedExportAllowed(){return !!mesh&&(!productionSelected()||(productionDraftVisible()&&!!purposeState.draft.scaled&&mesh===purposeState.draft.scaled&&purposeState.draft.size===Number($('prodSize').value)&&validProdSize()));}
function exportDraftName(){return productionSelected()?(productionDraftVisible()?'caratzon-production-CAD-review':'caratzon-original-with-stones-review'):mesh.name;}
function validProdSize(){const n=Number($('prodSize').value);return Number.isFinite(n)&&n>=1&&n<=500;}
