 $('prodRef').hidden=true;$('prodRefLabel').hidden=true;$('prodGenerate').hidden=true;$('modelPurpose').disabled=p.busy||p.rebuildQueued;$('prodRef').disabled=p.busy;$('prodGenerate').disabled=p.busy;$('prodReview').hidden=true;$('prodApprove').disabled=p.busy;$('prodCancel').disabled=p.busy;$('prodCheck').hidden=!production||!p.draft;$('prodSize').disabled=p.busy||p.rebuildQueued;$('prodConfirmed').disabled=p.busy||p.rebuildQueued||!validProdSize();
