(function(){
const box=document.createElement('section');box.style.cssText='display:grid;gap:8px;border:1px solid #806b45;padding:12px;border-radius:8px;margin:10px 0';box.innerHTML=`<strong>戒指精确尺寸 · Ring dimensions</strong><small>原款模式只校准可识别的戒圈底部截面，戒托区域保留并过渡；主石尺寸是设计目标。无法定位时保留原模型。/ Original shank draft: bottom section only, head preserved; no automatic stone-seat repair.</small><label>内圈直径 / Inner diameter (mm)<input id="r454d" type="number" value="16.5" min="10" max="30" step="0.01"></label><label>戒圈宽度 / Band width (mm)<input id="r454w" type="number" value="2.5" min="0.01" max="12" step="0.01"></label><label>戒圈厚度 / Radial thickness (mm)<input id="r454t" type="number" value="1.5" min="0.01" max="5" step="0.01"></label><label>原始内径校准 / Original bore calibration (mm)<input id="r456originalD" type="number" placeholder="默认以目标内径校准" min="10" max="30" step="0.01"></label><small>AI 模型未必有真实比例。若没有实测原内径，按目标内径校准整件的初始比例，原石托真实尺寸不能保证。/ If original scale is unknown, target bore establishes initial scale; real stone size unverified.</small><label>戒圈轴 / Bore axis<select id="r456axis"><option value="auto">AUTO / 自动识别</option><option>X</option><option>Y</option><option>Z</option></select></label><label>戒托方向 / Head direction<select id="r456up"><option>+Y</option><option>-Y</option><option>+X</option><option>-X</option><option>+Z</option><option>-Z</option></select></label><button type="button" id="r456apply" class="outline">按客户尺寸修改原戒圈 / Resize original shank</button><small id="r456warning" style="color:#d7aa70"></small><hr><small>独立标准圆形单石戒托模板（仅在明确选择时建立，不替换原款） / Optional separate round solitaire template</small><label>主石直径／长度 / Stone diameter or length (mm)<input id="r454s" type="number" placeholder="实际尺寸" step="0.01"></label><label>主石宽度目标 / Stone width target (mm)<input id="r456stoneW" type="number" placeholder="可选 / Optional" step="0.01"></label><label>主石高度目标 / Stone height target (mm)<input id="r456stoneH" type="number" placeholder="可选 / Optional" step="0.01"></label><label>模板镶爪 / Template prongs<select id="r454n"><option>4</option><option>6</option><option>3</option></select></label><button type="button" id="r454build" class="outline">另建标准圆石戒托 / Separate round template</button><button type="button" id="r454undo" class="outline">恢复原生产模型 / Restore original draft</button><small id="r454msg" style="white-space:pre-wrap" role="status"></small>`;
// Place outside hidden draft-only production controls.
$('productionControls').before(box);
let old=null,owner=null,applying=false;
function params(){const o={diameter:Number($('r454d').value),width:Number($('r454w').value),thickness:Number($('r454t').value),originalDiameter:Number($('r456originalD').value||$('r454d').value),axis:$('r456axis').value,up:$('r456up').value,stone:Number($('r454s').value),prongs:Number($('r454n').value)};if(![o.diameter,o.width,o.thickness].every(v=>Number.isFinite(v)&&v>0))throw Error('请输入正数尺寸 / Enter positive dimensions');return o;}
function warn(){const w=Number($('r454w').value),t=Number($('r454t').value);$('r456warning').textContent=w<1||t<1?'尺寸较小，可能变形或断裂；按输入值尝试，不会自动放大。/ Narrow or thin band: strength review required.':'尺寸为 CAD 草稿，需检查金属强度及石位。/ CAD review required.';}
for(const id of ['r454d','r454w','r454t','r456originalD','r456axis','r456up','r454s','r456stoneW','r456stoneH'])$(id).addEventListener('input',()=>{warn();if(!applying){purposeState.autoRing456=false;$('r454msg').textContent='尺寸已修改，尚未应用 / Changed; apply to update mesh';}});
function install(p,m,kind){if(owner!==p||!old){old={draft:p.draft,size:$('prodSize').value};owner=p;}const b=CZDownload453.bounds(m),span=Math.max(...b.hi.map((x,i)=>x-b.lo[i]));$('prodSize').value=span;p.draft={raw:m,scaled:m,size:Number($('prodSize').value),seat452Checked:true,qa:{status:'review',issues:[kind==='original'?'戒臂尺寸已按网格截面校准；需复核上部过渡、镶爪、承石位、碰撞与强度 / Shank sections calibrated; head, shoulders, seat and strength require CAD review':'标准圆石戒托草稿：未融合、需 CAD 及宝石尺寸复核 / Separate template; unfused and requires CAD review']},qaVersion:442};$('prodConfirmed').checked=false;showPurposeMesh('production');update();}
function applyOriginal(auto=false){const p=purposeState;if(applying)return;try{if(!productionSelected()||p.busy||p.rebuildQueued||!p.draft)throw Error('请先选择生产用途并准备无石草稿 / Open a production mounting draft first');applying=true;const o=params(),base=owner===p&&old?.draft?old.draft.raw:p.draft.raw;if(base.measure456||base.measure454)throw Error('请先恢复原款网格 / Restore the original mesh first');const m=o.axis==='auto'?CZRing456.auto(base,o,normals):CZRing456.resize(base,o,normals);const before=CZQuality.meshCheck({...base,span:Math.max(...CZDownload453.bounds(base).hi.map((v,i)=>v-CZDownload453.bounds(base).lo[i]))}),after=CZQuality.meshCheck({...m,span:Math.max(...CZDownload453.bounds(m).hi.map((v,i)=>v-CZDownload453.bounds(m).lo[i]))});if(after.faces!==before.faces||after.open>before.open||after.nonmanifold>before.nonmanifold||after.degenerate>before.degenerate)throw Error('网格拓扑检查失败，原模型保留 / Topology regression; original retained');install(p,m,'original');const a=m.measure456,b=a.before;$('r454msg').textContent=`实际截面 / Measured mesh (mm)
内径 / Bore: ${b.diameter.toFixed(3)} → ${a.diameter.toFixed(3)} (X/Y ${a.diameterX.toFixed(3)}/${a.diameterY.toFixed(3)})
底部宽度 / Bottom width: ${b.width.toFixed(3)} → ${a.width.toFixed(3)}
底部厚度 / Bottom thickness: ${b.thickness.toFixed(3)} → ${a.thickness.toFixed(3)}
保留三角面 / Faces retained: ${after.faces.toLocaleString()}
${a.axis?'Axis '+a.axis+' / '+a.up+' · ':''}尺寸已锁定；主石目标、肩位和强度未验证 / Dimensions locked; head and stone seat unverified.`;}
catch(e){$('r454msg').textContent='未完成尺寸校准，保留原模型 / Sizing not applied: '+e.message;}finally{applying=false;p.autoRing456=false;}}
$('r456apply').onclick=()=>applyOriginal();
const origUpdate=update;update=function(){origUpdate();const p=purposeState;box.hidden=!(p.display&&p.product449?.type==='ring');box.style.display=box.hidden?'none':'grid';let ready=productionSelected()&&!p.busy&&!p.rebuildQueued;$('r456apply').disabled=!ready||!p.draft;$('r454build').disabled=!ready;$('r454undo').disabled=owner!==p||!old||!ready;$('prodSize').readOnly=!!p.draft?.raw?.ring454;if(p.draft?.raw?.ring454)$('prodSizeLabel').textContent='实际最长边（已锁定） / Measured length (locked)';warn();if(p.autoRing456&&ready&&p.draft&&!p.draft.raw.ring454&&!applying){p.autoRing456=false;setTimeout(()=>{if(p===purposeState&&productionSelected())applyOriginal(true);},0);}};
$('r454build').onclick=()=>{try{const p=purposeState;if(!productionSelected()||p.busy||p.rebuildQueued)throw Error('Wait for production draft');const o=params(),w=Number($('r456stoneW').value);if(w>0&&Math.abs(w-o.stone)>.05)throw Error('独立模板只支持圆石 / Template supports round stones only');const m=CZRing454.build(o,normals);if(!confirm('另建标准圆石戒托草稿？不会保留原款装饰；原模型可恢复。 / Build a separate template? Original can be restored.'))return;install(p,m,'template');const a=m.measure454;$('r454msg').textContent=`模板实际网格 / Template measured: Ø ${a.diameter.toFixed(3)} mm · width ${a.width.toFixed(3)} mm · thickness ${a.thickness.toFixed(3)} mm · seat rail Ø ${a.seatRailDiameter.toFixed(2)} mm · ${a.prongs} prongs. 主石高度未验证；未融合 / Stone height unverified; not fused.`;}catch(e){$('r454msg').textContent=e.message;}};
$('r454undo').onclick=()=>{if(owner!==purposeState||!old)return;purposeState.draft=old.draft;$('prodSize').value=old.size;old=null;purposeState.autoRing456=false;showPurposeMesh('production');update();$('r454msg').textContent='原模型已恢复 / Restored';};update();})();

// V4.5.7: optional private CTB export, same sized mesh as STL.
async function czCTB457(bytes,name){
 const code=sessionStorage.getItem('cz-test');if(!code)throw Error('CTB requires studio access');
 const headers={'X-Studio-Code':code};
 async function req(action,job='',body=null){
  const q=new URLSearchParams({action});if(job)q.set('job',job);
  const r=await fetch('api/ctb?'+q,{method:body?'POST':'GET',headers:{...headers,...(body?{'Content-Type':'application/octet-stream'}:{})},body,cache:'no-store',signal:AbortSignal.timeout(60000)});
  if(!r.ok){const d=await r.json().catch(()=>({}));throw Error(d.error==='CTB_NOT_CONFIGURED'?'CTB: 打印机配置尚未启用 / Printer profile not configured':d.error||'CTB HTTP '+r.status);}
  return action==='file'?r.blob():r.json();
 }
 const h=await req('health');if(!h.ready)throw Error('CTB: 打印机配置尚未启用 / Printer profile not configured');
 if(!confirm('CTB: '+h.printer+'\n模型将发送到本地切片服务器。打印前请检查切片。 / Model sent to private slicer. Review before printing.'))throw Error('CTB cancelled');
 const {job}=await req('submit','',bytes);
 for(let i=0;i<255;i++){
  await new Promise(r=>setTimeout(r,2000));
  const j=await req('job',job);$('d453status').textContent='CTB · '+h.printer+' · '+j.state;
  if(j.state==='error')throw Error(j.error||'CTB failed');
  if(j.state==='done'){const blob=await req('file',job);dl(blob,name+'.ctb');return;}
 }
 throw Error('CTB timeout');
}
(function(){const old=$('saveSTL');if(!old)return;const b=document.createElement('button');b.type='button';b.id='saveCTB457';b.className=old.className;b.textContent='下载 CTB / Download CTB';old.after(b);const refresh=()=>{b.disabled=old.disabled;};new MutationObserver(refresh).observe(old,{attributes:true,attributeFilter:['disabled']});refresh();})();
